class Task:
    id: int
    title: str
    status: str
    priority: int = 0

    def as_dict(self) -> dict[str, object]:
        return {"id": self.id, "title": self.title, "status": self.status, "priority": self.priority}

class TaskStore:
    tasks: list[Task] = field(default_factory=list)

    def add(self, task: Task) -> Task:
        self.tasks.append(task)
        return task

    def list_tasks(self, status: str | None = None) -> list[dict[str, object]]:
        """Return tasks ordered by descending priority then ascending id.

        ``status`` optionally filters tasks by exact, case-sensitive status match.
        """

        tasks = filter_by_status(self.tasks, None if status == "*" else status)
        return [task.as_dict() for task in sorted(tasks, key=lambda item: (-item.priority, item.id))]

    def find_by_id(self, task_id: int) -> Task | None:
        for task in self.tasks:
            if task.id == task_id:
                return task
        return None

def add(self, task: Task) -> Task:
    self.tasks.append(task)
    return task

def find_by_id(self, task_id: int) -> Task | None:
    for task in self.tasks:
        if task.id == task_id:
            return task
    return None

def filter_by_status(tasks: Iterable[Task], status: str | None) -> list[Task]:
    """Return the tasks whose status equals ``status``; ``None`` keeps every task."""

    if status is None:
        return list(tasks)
    return [task for task in tasks if task.status == status]

